                            array_intersect($package_list[$key][$id_carrier]['carrier_list'], $data['carrier_list']);
                        $package_list[$key][$id_carrier]['product_list'] =
                            array_merge($package_list[$key][$id_carrier]['product_list'], $data['product_list']);

